Let $k$ be a positive integer and $\varepsilon>0$.
  For each $(k+\varepsilon n)$-weakly-partition-connected hypergraph $\mathcal{H}=([t],(e_1,\dots,e_n))$ with $t \ge 2$, we have, for $r=\lfloor {\varepsilon n/2} \rfloor$,
  \begin{align}
    \mathop{\bf Pr\/}_{\alpha_1,\dots,\alpha_n \sim \mathbb{F}_q\text{ distinct}} \left[ \mathsf{RIM}_{\mathcal{H}}(X_{[n]}=\alpha_{[n]})\text{ does not have full column rank} \right] \le \binom{n}{r}2^{tr}\cdot \left(\frac{(t-1)k}{q-n}\right)^r \ .

  \end{align}

For any sequence $i_1,\dots,i_{r}\in[n]$, over randomly chosen pairwise distinct evaluation points $\alpha_1 , \dots , \alpha_n$, we have

  \begin{align}
    \mathop{\bf Pr\/}\left[\mathtt{GetCertificate}(\alpha_1,\dots,\alpha_n) = (i_1,\dots,i_{r})\right] 
    \le \left(\frac{(t-1)k}{q-n}\right)^{r}.

  \end{align}
